"""CUET (UG) English (101): original passages and verbal-ability items, each read by hand for a single defensible answer."""
import re
RC, VA = "Reading Comprehension", "Verbal Ability"
def words(html): return len(re.sub(r"<[^>]+>", " ", html).split())

PASSAGES = {
"cu-mangrove": ("Factual passage: Mangroves", """<p>Along many tropical coasts, where rivers meet the sea, grow forests that seem to stand on stilts. These are mangroves, trees and shrubs that can survive in salty, waterlogged mud that would kill most other plants. Some mangroves filter much of the salt out at their roots; others get rid of it through their leaves. Because the mud holds very little oxygen, several species send up pencil-like roots from the ground. These breathing roots, called pneumatophores, take in air at low tide.</p>
<p>Mangroves matter far beyond the narrow strip they occupy. Their tangled roots slow down waves and trap sediment, so they help protect the shore from erosion and reduce the damage done by storm surges. The calm, shaded water between the roots is a nursery for young fish, crabs and prawns, many of which later move out to the open sea, where they support coastal fishing. Mangrove soils also store large amounts of carbon that would otherwise add to the carbon dioxide in the atmosphere.</p>
<p>Despite these benefits, mangroves have been cleared in many places for fish farms, ports and housing. Once removed, they are slow to return, because seedlings need sheltered mud and the right mix of fresh and salt water to take root. Restoration projects tend to succeed when local communities, who depend on the forest for fish and firewood, are involved in planting and protecting it. Without such involvement, newly planted areas are often lost again within a few years.</p>"""),
"cu-radio": ("Narrative passage: The radio", """<p>The radio had been silent for eleven years when Meera carried it down from the loft. It was a heavy wooden box with a cracked dial and a smell of dust and old varnish. Her grandfather watched from his chair as she set it on the table.</p>
<p>"It won't work," he said. "Nothing in it has worked since your grandmother passed away."</p>
<p>Meera said nothing. She had spent the summer helping at her uncle's repair shop, and she had learned that most broken things were not as broken as people believed. She unscrewed the back panel. Inside, among the glass valves and coloured wires, she found what she had half expected: a wire that had come loose from its terminal, its end green with corrosion.</p>
<p>It took her most of the afternoon. She cleaned the terminal, cut back the wire and borrowed her uncle's soldering iron. Her grandfather pretended to read the newspaper, but she noticed that he had not turned a page in an hour.</p>
<p>When she finally switched it on, there was only a low hum. Then, slowly, as the valves warmed, a voice rose out of the static, reading the evening news in the same calm tone the old man must have heard a thousand times.</p>
<p>He put down the newspaper. For a long moment he did not speak. Then he reached over and turned the dial, very carefully, to a station that played old film songs.</p>
<p>"She liked this one," he said quietly, and Meera understood that she had repaired more than a radio.</p>"""),
"cu-monsoon": ("Literary passage: The first rain", """<p>The first rain of the monsoon does not arrive so much as announce itself. For days the sky has been a sheet of tin, the air thick enough to lean on, and the city has waited with the irritable patience of a queue that has stopped moving. Then the wind changes. Leaves turn their pale undersides to the sky, as if to check what is coming, and somewhere a door bangs shut.</p>
<p>When the drops come, they are large and few, each one landing on the dusty road with a sound like a coin dropped on a table. Children run out before their mothers can stop them. Shopkeepers, who have spent the week complaining of the heat, stand in their doorways and complain instead about the mud, though their faces say otherwise.</p>
<p>And then there is the smell. The parched earth, touched by water, releases a scent so particular that we have borrowed a scientist's word, petrichor, to name it, though no word quite contains it. For a moment the whole city seems to breathe out.</p>
<p>By evening the gutters are rivers and the traffic has given up. Tomorrow there will be potholes, leaking roofs and the long grey weeks of the season. But tonight nobody is thinking of tomorrow. Tonight the rain is not weather; it is a reprieve.</p>"""),
}

def build(B):
    M = lambda *a, **k: B.mcq("english", *a, **k)
    for sid, (title, html) in PASSAGES.items():
        n = words(html); assert 200 <= n <= 300, (sid, n)        # official limit: passages of at most 300 words
        B.add_set(sid, "passage", title, f"<b>{title}</b>{html}")
    t = RC
    M(RC,t,"Easy","The main purpose of the passage is to:",["explain what mangroves are, why they are valuable and why protecting them is difficult","encourage the building of fish farms along tropical coasts","argue that mangroves should replace coastal towns","compare mangroves with tropical rainforests"],"explain what mangroves are, why they are valuable and why protecting them is difficult","Paragraph 1 describes mangroves, paragraph 2 their benefits, and paragraph 3 why they are lost and how restoration can work. The passage never promotes fish farms (they are a cause of clearing), never mentions replacing towns, and never compares mangroves with rainforests.",set_id="cu-mangrove")
    M(RC,t,"Easy","According to the passage, pneumatophores help mangroves to:",["take in air, because the mud holds very little oxygen","filter salt out of seawater","trap sediment carried by rivers","store carbon in the soil"],"take in air, because the mud holds very little oxygen","'These breathing roots, called pneumatophores, take in air at low tide', because 'the mud holds very little oxygen'. Salt filtering, trapping sediment and storing carbon are described separately and not linked to pneumatophores.",set_id="cu-mangrove")
    M(RC,t,"Medium","Which of the following is NOT mentioned in the passage as a benefit of mangroves?",["Providing timber for shipbuilding","Protecting the shore from erosion","Sheltering young fish, crabs and prawns","Storing carbon"],"Providing timber for shipbuilding","Erosion protection, the nursery role and carbon storage are all in paragraph 2. Timber for shipbuilding is never mentioned; the only wood use given is firewood for local communities.",set_id="cu-mangrove")
    M(RC,t,"Medium","According to the passage, newly planted mangroves are often lost again when:",["local communities are not involved in planting and protecting them","seedlings are planted in sheltered mud","the water has a mix of fresh and salt water","restoration projects are carried out"],"local communities are not involved in planting and protecting them","The last sentence says 'Without such involvement' (of local communities), newly planted areas are often lost again. Sheltered mud and the fresh/salt mix are conditions seedlings need, not causes of loss.",set_id="cu-mangrove")
    M(RC,t,"Easy","Why had the radio not been used for eleven years?",["It had stopped working around the time Meera's grandmother died","Meera's grandfather disliked listening to the news","It had been lent to Meera's uncle","Its glass valves had been removed"],"It had stopped working around the time Meera's grandmother died","The grandfather says: 'Nothing in it has worked since your grandmother passed away.' The valves were still inside, and nothing suggests he disliked the news or lent it out.",set_id="cu-radio")
    M(RC,t,"Medium","The detail that the grandfather 'had not turned a page in an hour' suggests that he:",["was quietly watching Meera's work with interest","was angry with Meera for opening the radio","was reading slowly because of poor eyesight","had fallen asleep in his chair"],"was quietly watching Meera's work with interest","He 'pretended to read the newspaper', so his attention was really on Meera and the radio. Nothing in the story suggests anger, eyesight problems or sleep.",set_id="cu-radio")
    M(RC,t,"Easy","What had Meera learned from her summer at the repair shop?",["That most broken things are not as broken as people believe","That old radios cannot be repaired","That soldering is too dangerous for beginners","That valves are more reliable than wires"],"That most broken things are not as broken as people believe","The passage states this directly: 'she had learned that most broken things were not as broken as people believed'.",set_id="cu-radio")
    M(RC,t,"Medium","The last line, 'she had repaired more than a radio', most likely means that:",["fixing the radio also brought back, for her grandfather, a connection to his late wife","she had also fixed the cracked dial","she would now open a repair shop of her own","the radio would never break again"],"fixing the radio also brought back, for her grandfather, a connection to his late wife","The radio had been silent since the grandmother's death, and the grandfather tunes it to a song 'She liked'. The 'more' that was repaired is emotional. The dial is never fixed, and nothing is said about a shop or the radio's future.",set_id="cu-radio")
    M(RC,t,"Medium","'The air thick enough to lean on' is an example of:",["Hyperbole","Simile","Onomatopoeia","Alliteration"],"Hyperbole","It is a deliberate exaggeration (air cannot really be leaned on) used to convey heavy humidity, which is hyperbole. It does not use 'like' or 'as' (simile), imitate a sound (onomatopoeia) or repeat initial consonants (alliteration).",set_id="cu-monsoon")
    M(RC,t,"Medium","'Leaves turn their pale undersides to the sky, as if to check what is coming' is an example of:",["Personification","Hyperbole","Irony","Onomatopoeia"],"Personification","The leaves are given a human intention ('to check what is coming'), which is personification.",set_id="cu-monsoon")
    M(RC,t,"Easy","The shopkeepers 'complain instead about the mud, though their faces say otherwise'. This suggests that they:",["are secretly glad that the rain has come","are angrier about the mud than they were about the heat","want the hot weather to return","are about to close their shops"],"are secretly glad that the rain has come","Their words complain, but 'their faces say otherwise', meaning their expressions show pleasure. The other options take the complaint at face value or add details that aren't there.",set_id="cu-monsoon")
    M(RC,t,"Easy","As used in the last line, the word 'reprieve' most nearly means:",["a welcome relief from something unpleasant","a punishment","a weather forecast","a public celebration"],"a welcome relief from something unpleasant","After days of oppressive heat, the rain is 'not weather' but relief, a temporary escape from something unpleasant. That is the meaning of reprieve.",set_id="cu-monsoon")
    t = "Synonyms & Antonyms"
    M(VA,t,"Easy","Choose the word closest in meaning to DILIGENT.",["Hard-working","Careless","Intelligent","Fortunate"],"Hard-working","Diligent means showing steady, careful effort, i.e. hard-working. Intelligent is a different quality, and careless is the opposite.")
    M(VA,t,"Easy","Choose the word closest in meaning to CANDID.",["Frank","Secretive","Polite","Cunning"],"Frank","Candid means honest and direct, i.e. frank. Secretive and cunning are nearly opposite, and polite is unrelated.")
    M(VA,t,"Easy","Choose the word closest in meaning to ABUNDANT.",["Plentiful","Scarce","Costly","Ancient"],"Plentiful","Abundant means existing in large quantities, i.e. plentiful. Scarce is its antonym.")
    M(VA,t,"Easy","Choose the word most nearly OPPOSITE in meaning to TRANSPARENT.",["Opaque","Clear","Fragile","Bright"],"Opaque","Transparent means that light passes through; opaque means that it does not. Clear is a synonym.")
    M(VA,t,"Easy","Choose the word most nearly OPPOSITE in meaning to EXPAND.",["Contract","Enlarge","Extend","Explode"],"Contract","To expand is to become larger; to contract is to become smaller. Enlarge and extend are synonyms.")
    t = "Choosing the correct word"
    M(VA,t,"Easy","Fill in the blank: The committee has not yet ______ a decision on the proposal.",["reached","arrived","done","made up"],"reached","'Reach a decision' is the standard collocation. 'Arrived' would need 'at'; 'done a decision' and 'made up a decision' are not idiomatic.")
    M(VA,t,"Medium","Fill in the blanks: She is good ______ mathematics but weak ______ spelling.",["at, in","in, at","on, with","with, on"],"at, in","The idioms are 'good at' a subject and 'weak in' a subject. Only the first pair puts 'at' after 'good'.")
    M(VA,t,"Medium","Fill in the blank: Neither the manager nor his assistants ______ present at the meeting.",["were","was","is","has been"],"were","With 'neither … nor', the verb agrees with the nearer subject, here the plural 'assistants', and the past tense fits 'at the meeting'. So 'were'.")
    t = "Error spotting"
    M(VA,t,"Medium","Identify the part of the sentence that contains an error: (A) Each of the students / (B) have submitted / (C) the project / (D) before the deadline.",["A","B","C","D"],"B","'Each' is singular, so the verb must be 'has submitted'. The error is in part B.",fixed=True)
    M(VA,t,"Medium","Identify the part of the sentence that contains an error: (A) He has been living / (B) in Pune / (C) since five years / (D) and likes it there.",["A","B","C","D"],"C","'Since' is used with a point in time (since 2020); a period of time takes 'for'. It should be 'for five years'. The error is in part C.",fixed=True)
    M(VA,t,"Hard","Identify the part of the sentence that contains an error: (A) If I would have known / (B) about the traffic, / (C) I would have left / (D) home earlier.",["A","B","C","D"],"A","In a third conditional, the if-clause takes the past perfect: 'If I had known…'. 'Would have' belongs only in the main clause (part C, which is correct). The error is in part A.",fixed=True)
    t = "Rearranging the parts"
    M(VA,t,"Medium","Rearrange the parts to form a meaningful sentence:<br>P: to the station &nbsp; Q: I ran all the way &nbsp; R: but still missed &nbsp; S: the last bus home",["QPRS","PRQS","QRSP","RSQP"],"QPRS","'I ran all the way (Q) to the station (P) but still missed (R) the last bus home (S).' QRSP gives 'the last bus home to the station', which contradicts itself (home or the station?). PRQS breaks 'missed … the last bus' apart, and RSQP begins with 'but' and leaves 'to the station' hanging.")
    M(VA,t,"Medium","The sentence begins: 'The children…'. Rearrange the parts to complete it:<br>P: that they fell asleep &nbsp; Q: were so tired &nbsp; R: on the sofa &nbsp; S: before dinner was served",["QPRS","PQRS","PSQR","RPQS"],"QPRS","'The children were so tired (Q) that they fell asleep (P) on the sofa (R) before dinner was served (S).' The 'so … that' pattern needs Q before P. Each other option puts 'that they fell asleep' before 'were so tired', which is ungrammatical.")
    M(VA,t,"Medium","Rearrange the parts to form a meaningful sentence:<br>P: the book &nbsp; Q: that you lent me &nbsp; R: is &nbsp; S: very interesting",["PQRS","PRQS","QRPS","RQSP"],"PQRS","'The book (P) that you lent me (Q) is (R) very interesting (S).' The relative clause Q must come right after the noun it describes, 'the book', and then the verb 'is' and its complement follow. PRQS, QRPS and RQSP all separate the clause from its noun or misplace the verb, giving ungrammatical strings.")
    t = "Match the following"
    M(VA,t,"Medium","Match each word in List I with its meaning in List II.<br>List I: (a) Benevolent (b) Meticulous (c) Ephemeral (d) Gregarious<br>List II: (i) lasting a very short time (ii) fond of the company of others (iii) kind and generous (iv) very careful about detail",["a–iii, b–iv, c–i, d–ii","a–iv, b–iii, c–ii, d–i","a–iii, b–i, c–iv, d–ii","a–ii, b–iv, c–i, d–iii"],"a–iii, b–iv, c–i, d–ii","Benevolent = kind and generous (iii); meticulous = very careful about detail (iv); ephemeral = lasting a very short time (i); gregarious = fond of company (ii).",fixed=True)
